-- ==========================================================================
-- SQL SCRIPT MIGRASI REAL DATA, HAPUS DUMMY, & RESET RIWAYAT UNTUK CLOUD DB
-- Compatible with phpPgAdmin / DewaCloud WebAdmin / DBeaver / pgAdmin
-- ==========================================================================

-- 1. RESET RIWAYAT TRANSAKSI BARANG MASUK & BARANG KELUAR
DELETE FROM "Barang_Masuk";
DELETE FROM "Barang_Keluar";

-- 2. SOFT-DELETE DATA DUMMY / UJI COBA LAMA
UPDATE "Master_Data"
SET is_deleted = TRUE
WHERE UPPER(bin) LIKE '%TEST%'
   OR UPPER(bin) LIKE '%BIN-TEST%'
   OR UPPER(bin) LIKE '%TEST-LOC%'
   OR UPPER(item) LIKE '%HAFID%'
   OR UPPER(item) LIKE '%TEST%'
   OR UPPER(brand) LIKE '%TESTING%'
   OR UPPER(brand) LIKE '%KONDISI: NEW%'
   OR UPPER(detail) LIKE '%AHAH%';

